const button = document.getElementById('requestPermission');
const statusMessage = document.getElementById('statusMessage');

button.addEventListener('click', async () => {
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        const videoElement = document.createElement('video');
        videoElement.srcObject = stream;
        videoElement.play();

        // Memeriksa izin dan pengaturan privasi
        const constraints = stream.getVideoTracks()[0].getSettings();
        console.log('Pengaturan Kamera:', constraints);

        // Contoh: Memeriksa apakah kamera diaktifkan
        if (constraints.active) {
            statusMessage.textContent = 'Kamera diaktifkan!';
        } else {
            statusMessage.textContent = 'Harap aktifkan kamera Anda.';
        }

        // Tutup stream setelah digunakan
        stream.getTracks().forEach(track => track.stop());
    } catch (error) {
        statusMessage.textContent = `Terjadi kesalahan: ${error.message}`;
    }
});
```

